import{_ as a,c as o,o as i,a2 as r}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Política de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy.md","filePath":"es/guide/privacy.md","lastUpdated":1793163976000}'),s={name:"es/guide/privacy.md"};function n(t,e,l,c,d,p){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="politica-de-privacidad" tabindex="-1">Política de privacidad <a class="header-anchor" href="#politica-de-privacidad" aria-label="Permalink to &quot;Política de privacidad&quot;">​</a></h1><p>NueZip está diseñado como una aplicación totalmente centrada en el uso sin conexión. Tu privacidad es nuestra prioridad.</p><h2 id="diseno-solo-local" tabindex="-1">Diseño solo local <a class="header-anchor" href="#diseno-solo-local" aria-label="Permalink to &quot;Diseño solo local&quot;">​</a></h2><ul><li>Todas las operaciones con archivos — compresión, extracción, conversión, cifrado — se ejecutan enteramente en tu Mac.</li><li>NueZip no sube tus archivos ni datos a ningún servidor externo.</li><li>No se requiere cuenta ni registro para usar la app.</li><li>No se requiere conexión a internet para el funcionamiento normal.</li></ul><h2 id="lo-que-no-recopilamos" tabindex="-1">Lo que no recopilamos <a class="header-anchor" href="#lo-que-no-recopilamos" aria-label="Permalink to &quot;Lo que no recopilamos&quot;">​</a></h2><ul><li>No recopilamos tus archivos, documentos ni contenidos de los archivos.</li><li>No rastreamos tu actividad, comportamiento de navegación o patrones de uso.</li><li>No enviamos ningún metadato de archivos ni información personal a servidores externos.</li><li>No incluimos analíticas de terceros, publicidad ni SDK de rastreo.</li><li>No tenemos ningún sistema de telemetría.</li></ul><h2 id="que-datos-se-almacenan-localmente" tabindex="-1">Qué datos se almacenan localmente <a class="header-anchor" href="#que-datos-se-almacenan-localmente" aria-label="Permalink to &quot;Qué datos se almacenan localmente&quot;">​</a></h2><p>Los siguientes datos se almacenan solo en tu dispositivo:</p><ul><li><strong>Ajustes de la app</strong>: Tema, preferencia de idioma, preferencias de compresión</li><li><strong>Clave de licencia</strong>: Si se compra (almacenada de forma segura en la cadena de claves local)</li><li><strong>Lista de archivos recientes</strong>: Archivos abiertos recientemente para acceso rápido</li><li><strong>Registros de contraseñas</strong>: Almacenados en tu cadena de claves local si eliges guardarlos</li><li><strong>Registros</strong>: Registros de depuración para solución de problemas (pueden eliminarse en cualquier momento)</li></ul><h2 id="permisos-usados-por-la-app" tabindex="-1">Permisos usados por la app <a class="header-anchor" href="#permisos-usados-por-la-app" aria-label="Permalink to &quot;Permisos usados por la app&quot;">​</a></h2><ul><li><strong>Archivos y carpetas</strong>: Requerido para leer archivos comprimidos y extraer contenidos.</li><li><strong>Extensión de Finder</strong>: Opcional, añade elementos de menú contextual con clic derecho en Finder.</li><li><strong>Notificaciones</strong>: Opcional, para avisos de finalización en tareas de larga duración.</li></ul><p>Puedes gestionar estos permisos en <strong>Configuración del sistema → Privacidad y seguridad</strong> en cualquier momento.</p><h2 id="compras-dentro-de-la-app-licencia" tabindex="-1">Compras dentro de la app / Licencia <a class="header-anchor" href="#compras-dentro-de-la-app-licencia" aria-label="Permalink to &quot;Compras dentro de la app / Licencia&quot;">​</a></h2><p>Las compras de licencias las procesa Apple a través de la Mac App Store. NueZip no recibe ni almacena tu información de pago. Los recibos de licencia se almacenan localmente para verificar la propiedad.</p><h2 id="servicios-de-terceros" tabindex="-1">Servicios de terceros <a class="header-anchor" href="#servicios-de-terceros" aria-label="Permalink to &quot;Servicios de terceros&quot;">​</a></h2><p>NueZip no incluye ningún servicio de analíticas, publicidad o rastreo de terceros. La app es totalmente autónoma.</p><h2 id="solicitudes-de-privacidad" tabindex="-1">Solicitudes de privacidad <a class="header-anchor" href="#solicitudes-de-privacidad" aria-label="Permalink to &quot;Solicitudes de privacidad&quot;">​</a></h2><p>Dado que NueZip almacena todos los datos localmente en tu dispositivo, no conservamos ningún dato personal en nuestros servidores. Si tienes preguntas sobre privacidad, por favor contáctanos.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h2><p>Para preguntas de privacidad, abre un issue en <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> o envíanos un correo electrónico.</p>',20)])])}const h=a(s,[["render",n]]);export{m as __pageData,h as default};
